const BY_ID = new Map(BNSS_SECTIONS.map((s) => [s.id, s]))

export function bnssSectionById(id: string) {
  return BY_ID.get(id)
}

export function bnssSectionsInChapter(chapter: string) {
  return BNSS_SECTIONS.filter((s) => s.chapter === chapter)
}

export function bnssSectionTopicId(sectionId: string) {
  return `s-${sectionId.toLowerCase()}`
}

export function bnssSectionIdFromTopicId(topicId: string): string | null {
  const match = topicId.match(/^s-(\d+[a-z]*)$/i)
  return match?.[1] ?? null
}

